  /* ---------------- reading them ---------------- */

  function get(id) {
    const g = GUIDES[id];
    return g ? { setup: g[0], move: g[1], watch: g[2] } : null;
  }
  function ids() { return Object.keys(GUIDES); }

  return { get: get, ids: ids, GUIDES: GUIDES };
